def calc(expr: str) -> int | str:
    def trunc_div(a: int, b: int) -> int:
        if b == 0:
            raise ZeroDivisionError
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    n = len(expr)
    i = 0

    def skip() -> None:
        nonlocal i
        while i < n and expr[i] == " ":
            i += 1

    def parse_expr() -> int:
        nonlocal i
        v = parse_term()
        while True:
            skip()
            if i < n and expr[i] in "+-":
                op = expr[i]
                i += 1
                r = parse_term()
                v = v + r if op == "+" else v - r
            else:
                break
        return v

    def parse_term() -> int:
        nonlocal i
        v = parse_unary()
        while True:
            skip()
            if i < n and expr[i] in "*/%":
                op = expr[i]
                i += 1
                r = parse_unary()
                if op == "*":
                    v *= r
                else:
                    q = trunc_div(v, r)
                    v = q if op == "/" else v - r * q
            else:
                break
        return v

    def parse_unary() -> int:
        nonlocal i
        skip()
        if i < n and expr[i] == "-":
            i += 1
            return -parse_unary()
        return parse_power()

    def parse_power() -> int:
        nonlocal i
        v = parse_primary()
        skip()
        if i < n and expr[i] == "^":
            i += 1
            e = parse_unary()
            if e < 0:
                raise ValueError
            v = v ** e
        return v

    def parse_primary() -> int:
        nonlocal i
        skip()
        if expr[i] == "(":
            i += 1
            v = parse_expr()
            skip()
            i += 1
            return v
        j = i
        while j < n and expr[j].isdigit():
            j += 1
        v = int(expr[i:j])
        i = j
        return v

    try:
        return parse_expr()
    except (ZeroDivisionError, ValueError):
        return "error"
